#!/usr/bin/env python3
"""Task-local inspection of report.pdf: locate the file and print its metadata."""
import os
import sys

from pypdf import PdfReader


def find_report(start="."):
    for root, dirs, files in os.walk(start):
        if ".codex" in root:
            continue
        for name in files:
            if name == "report.pdf":
                return os.path.join(root, name)
    return None


def main():
    path = find_report()
    if path is None:
        print("REPORT_PDF: NOT FOUND")
        print("CWD:", os.getcwd())
        for name in sorted(os.listdir(".")):
            print("  entry:", name)
        return 1

    print("REPORT_PDF:", os.path.abspath(path))
    reader = PdfReader(path)
    print("PAGES:", len(reader.pages))
    if reader.pages:
        box = reader.pages[0].mediabox
        print("FIRST_PAGE_MEDIABOX:", float(box.width), float(box.height))
    meta = reader.metadata
    print("META:", meta)
    return 0


if __name__ == "__main__":
    sys.exit(main())
